#include <vector>
#include <algorithm>

class Solution {
    long long total_increments = 0;
public:
    int minIncrements(int n, std::vector<std::vector<int>>& edges, std::vector<int>& weights) {
        total_increments = 0;
        std::vector<std::vector<std::pair<int, int>>> adj(n);
        for (size_t i = 0; i < edges.size(); ++i) {
            int u = edges[i][0], v = edges[i][1], w = weights[i];
            adj[u].push_back({v, w});
            adj[v].push_back({u, w});
        }

        auto dfs = [&](auto& self, int u, int p) -> long long {
            std::vector<long long> branch_lens;
            for (const auto& [v, w] : adj[u]) {
                if (v == p) continue;
                branch_lens.push_back(w + self(self, v, u));
            }
            if (branch_lens.empty()) return 0;

            long long max_len = *std::max_element(branch_lens.begin(), branch_lens.end());
            for (long long l : branch_lens) {
                total_increments += (max_len - l);
            }
            return max_len;
        };

        dfs(dfs, 0, -1);
        return (int)total_increments;
    }
};

import java.util.*;

class Solution {
    private long totalIncrements = 0;

    public int minIncrements(int n, int[][] edges, int[] weights) {
        totalIncrements = 0;
        List<List<int[]>> adj = new ArrayList<>(n);
        for (int i = 0; i < n; i++) adj.add(new ArrayList<>());
        for (int i = 0; i < edges.length; i++) {
            int u = edges[i][0], v = edges[i][1], w = weights[i];
            adj.get(u).add(new int[]{v, w});
            adj.get(v).add(new int[]{u, w});
        }

        dfs(0, -1, adj);
        return (int) totalIncrements;
    }

    private long dfs(int u, int p, List<List<int[]>> adj) {
        List<Long> branchLens = new ArrayList<>();
        for (int[] edge : adj.get(u)) {
            int v = edge[0], w = edge[1];
            if (v == p) continue;
            branchLens.add(w + dfs(v, u, adj));
        }
        if (branchLens.isEmpty()) return 0;

        long maxLen = Collections.max(branchLens);
        for (long l : branchLens) {
            totalIncrements += (maxLen - l);
        }
        return maxLen;
    }
}

/**
 * @param {number} n
 * @param {number[][]} edges
 * @param {number[]} weights
 * @return {number}
 */
var minIncrements = function(n, edges, weights) {
    let totalIncrements = 0;
    const adj = Array.from({ length: n }, () => []);
    for (let i = 0; i < edges.length; i++) {
        const [u, v] = edges[i];
        const w = weights[i];
        adj[u].push([v, w]);
        adj[v].push([u, w]);
    }

    const dfs = (u, p) => {
        const branchLens = [];
        for (const [v, w] of adj[u]) {
            if (v === p) continue;
            branchLens.push(w + dfs(v, u));
        }
        if (branchLens.length === 0) return 0;

        const maxLen = Math.max(...branchLens);
        for (const l of branchLens) {
            totalIncrements += (maxLen - l);
        }
        return maxLen;
    };

    dfs(0, -1);
    return totalIncrements;
};
